// Extract and sanitize inbound student inquiry
const body = $input.item.json.body || $input.item.json;
const query = (body.query || body.message || body.text || '').trim();
const sessionId = body.session_id || body.sessionId || 'session_' + Math.random().toString(36).substring(2, 9);
const userId = body.user_id || body.userId || 'web_applicant';

if (!query) {
  return [{
    json: {
      error: true,
      message: 'Query parameter is required',
      status_code: 400
    }
  }];
}

return [{
  json: {
    query: query,
    session_id: sessionId,
    user_id: userId,
    timestamp: new Date().toISOString()
  }
}];

// Log human escalation and format response payload
const data = $input.item.json;
const ticketId = data.ticket_id || 'ESC-' + new Date().getFullYear() + '-' + Math.floor(1000 + Math.random() * 9000);

return [{
  json: {
    success: true,
    status: 'escalated_to_human',
    ticket_id: ticketId,
    response: data.response,
    action_buttons: data.action_buttons || [],
    escalation_reason: 'low_confidence_or_out_of_scope',
    admissions_email: 'admisiones@novaidiomas.edu.co',
    admissions_whatsapp: '+57 300 912 3456',
    meta: {
      confidence_score: data.confidence_score || 0.0,
      latency_ms: data.latency_ms || 0,
      cached: data.cached || false
    }
  }
}];

// Format standard RAG response
const data = $input.item.json;

return [{
  json: {
    success: true,
    status: 'ai_grounded_response',
    response: data.response,
    sources: data.sources || [],
    action_buttons: data.action_buttons || [],
    is_escalated: false,
    meta: {
      confidence_score: data.confidence_score || 1.0,
      latency_ms: data.latency_ms || 0,
      cached: data.cached || false,
      tokens_used: data.tokens_used || 0,
      estimated_cost_usd: data.estimated_cost_usd || 0.0
    }
  }
}];
